package com.railway.servlet;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.time.LocalDate;import java.util.*;import com.railway.model.User;import com.railway.service.BookingService;
public class BookingServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/booking-form.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)r.getSession(false).getAttribute("user");long train=Long.parseLong(r.getParameter("trainId"));LocalDate date=LocalDate.parse(r.getParameter("journeyDate"));int count=Integer.parseInt(r.getParameter("passengerCount"));if(count<1||count>6)throw new IllegalArgumentException("Passenger count must be between 1 and 6.");List<BookingService.Passenger> ps=new ArrayList<>();for(int i=0;i<count;i++){String name=r.getParameter("name"+i),age=r.getParameter("age"+i),gender=r.getParameter("gender"+i);ps.add(new BookingService.Passenger(name,Integer.parseInt(age),gender));}String pnr=new BookingService().reserve(u.getId(),train,date,ps);s.sendRedirect(r.getContextPath()+"/booking-details?pnr="+pnr);}catch(IllegalArgumentException e){r.setAttribute("error",e.getMessage());doGet(r,s);}catch(Exception e){getServletContext().log("Booking failed",e);r.setAttribute("error","Booking could not be completed. Check the schedule and available seats.");doGet(r,s);}}}
